<script>
  let klass = ''
  export { klass as class }
  export let title, id, hash

  let src = `https://player.vimeo.com/video/${id}`
  if (hash) src += `?h=${hash}`
</script>

<div class={`Vimeo ${klass}`}>
  <iframe
    allow="autoplay; fullscreen; picture-in-picture"
    allowfullscreen
    frameborder="0"
    {src}
    {title}
  ></iframe>
</div>
